from copy import deepcopy
from collections.abc import Mapping


class MissingRecords(Exception):
    pass


def format_offset(total_seconds, separator=":"):
    if type(total_seconds) is not int or not 0 <= total_seconds <= 86399:
        raise ValueError("total_seconds must be in 0..86399")
    if not isinstance(separator, str) or not separator:
        raise ValueError("separator must be non-empty")
    hours, remainder = divmod(total_seconds, 3600)
    minutes, seconds = divmod(remainder, 60)
    return f"{hours:02d}{separator}{minutes:02d}{separator}{seconds:02d}"


def parse_offset(text, separator=":"):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if not isinstance(separator, str) or not separator:
        raise ValueError("separator must be non-empty")
    parts = text.strip().split(separator)
    if len(parts) != 3 or any(
        len(part) != 2 or not part.isdecimal() for part in parts
    ):
        raise ValueError("malformed offset")
    hours, minutes, seconds = map(int, parts)
    if hours > 23 or minutes > 59 or seconds > 59:
        raise ValueError("offset component out of range")
    return hours * 3600 + minutes * 60 + seconds


def normalize_envelope(response, tag):
    if not isinstance(response, Mapping):
        raise ValueError("response must be a mapping")
    if not isinstance(tag, str) or not tag:
        raise ValueError("tag must be non-empty")
    errors = response.get("errors", [])
    payload = response.get("payload", {})
    if not isinstance(errors, list) or not isinstance(payload, Mapping):
        raise ValueError("malformed envelope")
    if errors:
        raise MissingRecords("response contains errors")
    if tag not in payload:
        raise MissingRecords("tag is absent")
    records = payload[tag]
    if not isinstance(records, list):
        raise ValueError("tag value must be a list")
    if not records:
        raise MissingRecords("record list is empty")
    result = []
    for record in records:
        if not isinstance(record, Mapping):
            raise ValueError("each record must be a mapping")
        item = deepcopy(dict(record))
        for key in ("device_id", "module_id"):
            if key in item and isinstance(item[key], str):
                item[key] = item[key].strip()
        result.append(item)
    return {"records": result, "errors": errors}

